Arenas arenas(Reader& r){return{r.bytes(0xb000),r.bytes(0x1000),r.bytes(0x1000),r.bytes(0x1000)};}
void same(const Arenas& a,const Arenas& b,const std::string& message){same(a.player,b.player,message+" player");same(a.pbw,b.pbw,message+" pbw");same(a.pw,b.pw,message+" pw");same(a.global,b.global,message+" global");}
std::vector<mp::Layer> joined(const pa::State& state){auto layers=state.frame.animation.layers;layers.insert(layers.end(),state.inactive.begin(),state.inactive.end());return layers;}
Arenas encode_state(const Arenas& before,const pa::State& state,const Context& context,const Bindings& events){auto output=before;output.player=encode(before.player,joined(state),state.controller.motion,context,events);encode_controller(output,state.controller);return output;}
