 const auto ncalls=in.integer(),ntrace=in.integer(),routed=in.integer();check(entry<3&&ncalls<=2&&ntrace<=100&&routed<=1,"Observation bounds");ps::AnimationRequest route{};if(routed){route.selector=in.integer();route.mode=in.integer();route.interpolation_bits=in.integer();route.frame_bits=in.integer();}
 std::vector<std::array<std::uint32_t,8>> calls;for(unsigned i=0;i<ncalls;++i){std::array<std::uint32_t,8> call;for(auto& word:call)word=in.integer();calls.push_back(call);}unsigned nq=0,ns=0;for(unsigned i=0;i<ntrace;++i){const auto kind=in.integer();in.integer();const auto last=in.integer();check(kind==1||kind==2,"Trace kind");if(kind==1){++nq;check(last==0,"Original Q output omitted");}else ++ns;}
 const auto transitioned=in.integer();check(transitioned<=1,"Transition marker");std::array<std::uint32_t,4> transition{};if(transitioned)for(auto& v:transition)v=in.integer();const auto dispatched=in.integer();check(dispatched<=1,"Dispatch marker");std::array<std::uint32_t,2> dispatch{};if(dispatched)for(auto& v:dispatch)v=in.integer();check(in.p==body.size(),"No record tail");
