  rq::Model model;model.skeleton_present=word(before.player,0xf0)!=0;check(word(before.player,0x234)==2,"Explicit player active count");for(unsigned bank=0;bank<16;++bank){const auto address=word(before.player,0xc04+4*bank);if(!address){model.banks[bank]=rq::Absent{};continue;}check(address>=0x2700000&&(address-0x2700000)%128==0&&(address-0x2700000)/128<sources.size(),"Known resource wrapper");model.banks[bank]=sources[(address-0x2700000)/128].resource.request_resource();}
