int main(int argc,char** argv){try{if(argc!=11)throw std::runtime_error("Usage: player-animation-resource-tests fixture sha constants sha entry path sha entry path sha");const auto fixture=read(argv[1],128U*1024U*1024U);check(picosha2::hash256_hex_string(fixture)==argv[2],"Fixture identity");auto decoded=pt::Constants::decode(read(argv[3],88),{argv[4],"d4191ea404df1e9ade8fb401983e3497699dae5aa994937f7859c43f84403435"});if(auto* e=std::get_if<pt::Error>(&decoded))throw std::runtime_error(std::string(e->message));std::vector<Source> sources;for(int i=5;i<argc;i+=3){std::size_t end{};const std::string text=argv[i];const auto entry=std::stoull(text,&end);check(end==text.size()&&entry<=0xffffffff,"Source ID");auto resource=mr::Resource::load(argv[i+1],argv[i+2]);if(auto* e=std::get_if<mr::Error>(&resource))throw std::runtime_error(e->message);sources.push_back({std::uint32_t(entry),sources.empty()?0x5000000U:0x6000000U,std::get<mr::Resource>(std::move(resource))});}oracle(fixture,sources,std::get<pt::Constants>(decoded));return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
